import pandas as pd
import os
import numpy as np

files = ['experiment_1_csv', 'experiment_2_csv', 'experiment_3_csv', 'experiment_4_csv', 'experiment_5_csv']
dfs = []
for f in files:
    if f in dir():
        try:
            df = pd.read_csv(eval(f))
            df['source'] = f
            dfs.append(df)
        except Exception as e:
            print(f"Error loading {f}: {e}")

if not dfs:
    print("No dataframes loaded. Checking variable names directly...")
    for f in files:
        if f in dir():
            print(f"{f} = {eval(f)}")
else:
    combined = pd.concat(dfs, ignore_index=True)
    print("Combined shape:", combined.shape)
    print("\nColumns:", combined.columns.tolist())
    print("\nHead:")
    print(combined.head())
    print("\nDescribe:")
    print(combined.describe().round(2))

    # Check correlations with ReadmissionRate if it exists
    if 'ReadmissionRate' in combined.columns:
        print("\nCorrelations with ReadmissionRate:")
        print(combined.corr(numeric_only=True)['ReadmissionRate'].sort_values(ascending=False))

import pandas as pd
import os

# Load all available experiments
dfs = {}
for i in range(1, 6):
    var_name = f'experiment_{i}_csv'
    if var_name in dir():
        path = eval(var_name)
        dfs[i] = pd.read_csv(path)
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(dfs[i].columns)}")
        print(f"Shape: {dfs[i].shape}")
        print(dfs[i].head(3))
        print(dfs[i].describe().round(2))
    else:
        print(f"\nExperiment {i} variable not found in namespace")
        # Try to find CSV files in common locations
        for f in os.listdir('.'):
            if f.startswith('experiment') and f.endswith('.csv'):
                print(f"  Found file: {f}")
